using MarketSphere.Domain.Entities.CRM;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace MarketSphere.Infrastructure.Persistence.Configurations.CRM;
public sealed class CRMTaskConfiguration : IEntityTypeConfiguration<CRMTask> { public void Configure(EntityTypeBuilder<CRMTask> b) { b.ToTable("CRMTasks", t => t.HasCheckConstraint("CK_CRMTasks_CompletedAt", "[Status] <> 3 OR [CompletedAt] IS NOT NULL")); b.HasKey(x => x.CRMTaskID); b.Property(x => x.Title).HasMaxLength(200).IsRequired(); b.Property(x => x.Description).HasColumnType("nvarchar(max)"); b.Property(x => x.RecurrenceRule).HasMaxLength(500); b.HasIndex(x => new { x.AssignedEmployeeID, x.Status, x.DueAt }); b.HasOne(x => x.Lead).WithMany().HasForeignKey(x => x.LeadID).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.Client).WithMany().HasForeignKey(x => x.ClientID).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.Opportunity).WithMany().HasForeignKey(x => x.OpportunityID).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.Complaint).WithMany().HasForeignKey(x => x.ComplaintID).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.ReactivationCase).WithMany().HasForeignKey(x => x.ReactivationCaseID).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.AssignedEmployee).WithMany().HasForeignKey(x => x.AssignedEmployeeID).OnDelete(DeleteBehavior.Restrict); } }
